1	//nolint:ireturn // bubbletea model methods in this file must return framework interfaces
2	package summarytui
3	
4	import (
5		"context"
6		"fmt"
7		"strconv"
8		"strings"
9	
10		"github.com/charmbracelet/bubbles/key"
11		"github.com/charmbracelet/bubbles/paginator"
12		"github.com/charmbracelet/bubbles/table"
13		tea "github.com/charmbracelet/bubbletea"
14		"github.com/entireio/cli/cmd/entire/cli/insightsdb"
15	)
16	
17	const defaultPageSize = 10
18	const rootVerticalChrome = 6
19	
20	type branchFilter int
21	
22	const (
23		filterRepo          branchFilter = iota // default branch (main/master)
24		filterCurrentBranch                     // current working branch
25		filterAllBranches                       // all branches
26	)
27	
28	//nolint:recvcheck // bubbletea pattern: value receiver for interface, pointer receivers for mutation helpers
29	type rootModel struct {
30		ctx           context.Context
31		rows          []insightsdb.SessionRow
32		filteredRows  []insightsdb.SessionRow
33		currentBranch string
34		filter        branchFilter
35		table         table.Model
36		paginator     paginator.Model
37		pageSize      int
38		width         int
39		height        int
40		styles        styles
41		detailPage    *detailModel
42	}
43	
44	type openDetailMsg struct {
45		row insightsdb.SessionRow
46	}
47	
48	type closeDetailMsg struct{}
49	
50	func Run(ctx context.Context, rows []insightsdb.SessionRow) error {
51		return RunWithCurrentBranch(ctx, rows, "")
52	}
53	
54	func RunWithCurrentBranch(_ context.Context, rows []insightsdb.SessionRow, currentBranch string) error {
55		p := tea.NewProgram(newRootModel(rows, currentBranch), tea.WithAltScreen())
56		_, err := p.Run()
57		if err != nil {
58			return fmt.Errorf("run summary TUI: %w", err)
59		}
60		return nil
61	}
62	
63	func newRootModel(rows []insightsdb.SessionRow, currentBranch string) rootModel {
64		columns := []table.Column{
65			{Title: "TIME", Width: 16},
66			{Title: "AGENT", Width: 14},
67			{Title: "BRANCH", Width: 24},
68			{Title: "CHECKPOINT", Width: 12},
69			{Title: "TOKENS", Width: 8},
70		}
71		styles := newStyles()
72		t := table.New(table.WithColumns(columns), table.WithFocused(true))
73		t.SetStyles(styles.tableStyles())
74		p := paginator.New()
75		p.PerPage = defaultPageSize
76		m := rootModel{
77			ctx:           context.Background(),
78			rows:          append([]insightsdb.SessionRow(nil), rows...),
79			currentBranch: currentBranch,
80			filter:        filterRepo,
81			table:         t,
82			paginator:     p,
83			pageSize:      defaultPageSize,
84			styles:        styles,
85			width:         100,
86			height:        30,
87		}
88		m.rebuildFilteredRows()
89		return m
90	}
91	
92	func (m rootModel) Init() tea.Cmd {
93		return nil
94	}
95	
96	//nolint:ireturn // required by bubbletea Model interface
97	func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
98		switch msg := msg.(type) {
99		case tea.WindowSizeMsg:
100			m.resize(msg.Width, msg.Height)
101			if m.detailPage != nil {
102				m.detailPage.setSize(m.width, m.height)
103			}
104			return m, nil
105	
106		case tea.KeyMsg:
107			if m.detailPage != nil {
108				//nolint:exhaustive // only quit/back keys are handled here; all others delegate to the viewport
109				switch msg.Type {
110				case tea.KeyEsc:
111					return m, func() tea.Msg { return closeDetailMsg{} }
112				case tea.KeyCtrlC:
113					return m, tea.Quit
114				default:
115				}
116				var cmd tea.Cmd
117				*m.detailPage, cmd = m.detailPage.update(msg)
118				return m, cmd
119			}
120	
121			switch {
122			case key.Matches(msg, keys.cycleFilter):
123				m.cycleFilter()
124				return m, nil
125			case key.Matches(msg, keys.nextPage):
126				m.nextPage()
127				return m, nil
128			case key.Matches(msg, keys.prevPage):
129				m.prevPage()
130				return m, nil
131			}
132	
133			//nolint:exhaustive // only command-specific keys are handled here; all others fall through to the table widget
134			switch msg.Type {
135			case tea.KeyEnter:
136				if row := m.selectedRow(); row != nil {
137					selected := *row
138					return m, func() tea.Msg { return openDetailMsg{row: selected} }
139				}
140			case tea.KeyCtrlC:
141				return m, tea.Quit
142			default:
143			}
144	
145		case openDetailMsg:
146			m.detailPage = newDetailModel(m.styles, msg.row)
147			m.detailPage.setSize(m.width, m.height)
148			return m, nil
149	
150		case closeDetailMsg:
151			m.detailPage = nil
152			return m, nil
153		}
154	
155		var cmd tea.Cmd
156		m.table, cmd = m.table.Update(msg)
157		return m, cmd
158	}
159	
160	func (m rootModel) View() string {
161		if m.detailPage != nil {
162			return m.detailPage.view()
163		}
164	
165		var b strings.Builder
166		b.WriteString(m.styles.render(m.styles.appTitle, "SESSION SUMMARY"))
167		b.WriteString("\n\n")
168		b.WriteString(renderFilterChips(m.styles, m.filter))
169		b.WriteString("  ")
170		b.WriteString(m.styles.render(m.styles.dim, pageLabel(m.paginator)))
171		b.WriteString("\n\n")
172		b.WriteString(m.table.View())
173		b.WriteString("\n\n")
174		b.WriteString(m.styles.render(m.styles.statusBar, "j/k navigate  f filter  ←/→ page  enter detail  q quit"))
175		return b.String()
176	}
177	
178	func (m *rootModel) rebuildFilteredRows() {
179		m.filteredRows = m.applyFilter()
180		m.paginator.PerPage = m.pageSize
181		totalPages := m.paginator.SetTotalPages(len(m.filteredRows))
182		if totalPages == 0 {
183			m.paginator.TotalPages = 1
184		}
185		if m.paginator.Page >= m.paginator.TotalPages {
186			m.paginator.Page = max(0, m.paginator.TotalPages-1)
187		}
188		if m.paginator.Page < 0 {
189			m.paginator.Page = 0
190		}
191		m.rebuildTable()
192	}
193	
194	func (m *rootModel) rebuildTable() {
195		pageRows := m.currentPageRows()
196		rows := make([]table.Row, 0, len(pageRows))
197		for _, row := range pageRows {
198			checkpoint := row.CheckpointID
199			if len(checkpoint) > 12 {
200				checkpoint = checkpoint[:12]
201			}
202			rows = append(rows, table.Row{
203				row.CreatedAt.Format("2006-01-02 15:04"),
204				row.Agent,
205				truncate(row.Branch, 24),
206				checkpoint,
207				strconv.Itoa(row.TotalTokens),
208			})
209		}
210		m.table.SetRows(rows)
211		if len(rows) == 0 {
212			m.table.SetCursor(0)
213			return
214		}
215		if m.table.Cursor() >= len(rows) {
216			m.table.SetCursor(len(rows) - 1)
217		}
218	}
219	
220	func (m rootModel) selectedRow() *insightsdb.SessionRow {
221		rows := m.currentPageRows()
222		idx := m.table.Cursor()
223		if idx < 0 || idx >= len(rows) {
224			return nil
225		}
226		return &rows[idx]
227	}
228	
229	func (m rootModel) applyFilter() []insightsdb.SessionRow {
230		filtered := make([]insightsdb.SessionRow, 0, len(m.rows))
231		for _, row := range m.rows {
232			if m.filter == filterRepo && row.Branch != "main" && row.Branch != "master" {
233				continue
234			}
235			if m.filter == filterCurrentBranch && m.currentBranch != "" && row.Branch != m.currentBranch {
236				continue
237			}
238			filtered = append(filtered, row)
239		}
240		return filtered
241	}
242	
243	func (m rootModel) currentPageRows() []insightsdb.SessionRow {
244		if len(m.filteredRows) == 0 {
245			return nil
246		}
247		start, end := m.paginator.GetSliceBounds(len(m.filteredRows))
248		if start >= len(m.filteredRows) {
249			return nil
250		}
251		if end > len(m.filteredRows) {
252			end = len(m.filteredRows)
253		}
254		return m.filteredRows[start:end]
255	}
256	
257	func (m *rootModel) cycleFilter() {
258		m.filter = (m.filter + 1) % 3
259		m.paginator.Page = 0
260		m.table.SetCursor(0)
261		m.rebuildFilteredRows()
262	}
263	
264	func (m *rootModel) nextPage() {
265		if m.paginator.OnLastPage() {
266			return
267		}
268		m.paginator.NextPage()
269		m.table.SetCursor(0)
270		m.rebuildTable()
271	}
272	
273	func (m *rootModel) prevPage() {
274		if m.paginator.OnFirstPage() {
275			return
276		}
277		m.paginator.PrevPage()
278		m.table.SetCursor(0)
279		m.rebuildTable()
280	}
281	
282	func pageLabel(p paginator.Model) string {
283		return fmt.Sprintf("Page %d/%d", p.Page+1, max(1, p.TotalPages))
284	}
285	
286	func renderFilterChips(styles styles, active branchFilter) string {
287		labels := []struct {
288			filter branchFilter
289			label  string
290		}{
291			{filterRepo, "Repo"},
292			{filterCurrentBranch, "Current Branch"},
293			{filterAllBranches, "All"},
294		}
295	
296		parts := make([]string, 0, len(labels))
297		for _, item := range labels {
298			text := item.label
299			if item.filter == active {
300				text = "[" + text + "]"
301				parts = append(parts, styles.render(styles.chipActive, text))
302				continue
303			}
304			parts = append(parts, styles.render(styles.chipInactive, text))
305		}
306		return strings.Join(parts, " ")
307	}
308	
309	func (m *rootModel) resize(width, height int) {
310		selectedSessionID := ""
311		if selected := m.selectedRow(); selected != nil {
312			selectedSessionID = selected.SessionID
313		}
314	
315		m.width = width
316		m.height = height
317		m.table.SetWidth(width)
318	
319		tableHeight := max(3, height-rootVerticalChrome)
320		m.table.SetHeight(tableHeight)
321		m.pageSize = max(1, tableHeight-1)
322	
323		m.rebuildFilteredRows()
324		m.restoreSelection(selectedSessionID)
325	}
326	
327	func (m *rootModel) restoreSelection(sessionID string) {
328		if sessionID == "" || len(m.filteredRows) == 0 {
329			return
330		}
331	
332		for idx, row := range m.filteredRows {
333			if row.SessionID != sessionID {
334				continue
335			}
336	
337			m.paginator.Page = idx / m.pageSize
338			m.rebuildTable()
339	
340			cursor := idx % m.pageSize
341			if pageRows := m.currentPageRows(); len(pageRows) > 0 && cursor >= len(pageRows) {
342				cursor = len(pageRows) - 1
343			}
344			m.table.SetCursor(cursor)
345			return
346		}
347	}
